{"command":"cat << 'EOF' > src/args.cc
#include "args.h"
#include <iostream>
#include <stdexcept>
#include <cstdint>

Args::Args() {
  input = "";
  output = "";
  lr = 0.05;
  lrUpdateRate = 100;
  dim = 100;
  ws = 5;
  epoch = 5;
  minCount = 5;
  minCountLabel = 0;
  neg = 5;
  wordNgrams = 1;
  loss = loss_name::ns;
  model = model_name::sg;
  bucket = 2000000;
  minn = 3;
  maxn = 6;
  thread = 12;
  t = 1e-4;
  label = "__label__";
  verbose = 2;
  pretrainedVectors = "";
  saveOutput = false;
  seed = 0;

  autotuneValidation = "";
  autotuneMetric = "f1";
  autotunePredictions = 1;
  autotuneDuration = 300;
  autotuneModelSize = "";

  cutoff = 0;
  retrain = false;
  qnorm = false;
  qout = false;
  dsub = 2;

  manualArgsSet_ = false;
}

static std::string lossToString(loss_name l) {
  if (l == loss_name::hs) return "hs";
  if (l == loss_name::ns) return "ns";
  if (l == loss_name::softmax) return "softmax";
  if (l == loss_name::ova) return "one-vs-all";
  return "ns";
}

static std::string modelToString(model_name m) {
  if (m == model_name::cbow) return "cbow";
  if (m == model_name::sg) return "sg";
  if (m == model_name::sup) return "sup";
  return "sg";
}

bool Args::hasAutotune() const {
  return !autotuneValidation.empty();
}

void Args::printHelp() {
  std::cout << "\nThe following arguments are mandatory:" << std::endl;
  std::cout << "  -input              training file path" << std::endl;
  std::cout << "  -output             output file path" << std::endl;
  std::cout << "\nThe following arguments are optional:" << std::endl;
  std::cout << "  -verbose            verbosity level [" << verbose << "]" << std::endl;
  std::cout << "\nThe following arguments for the dictionary are optional:" << std::endl;
  std::cout << "  -minCount           minimal number of word occurences [" << minCount << "]" << std::endl;
  std::cout << "  -minCountLabel      minimal number of label occurences [" << minCountLabel << "]" << std::endl;
  std::cout << "  -wordNgrams         max length of word ngram [" << wordNgrams << "]" << std::endl;
  std::cout << "  -bucket             number of buckets [" << bucket << "]" << std::endl;
  std::cout << "  -minn               min length of char ngram [" << minn << "]" << std::endl;
  std::cout << "  -maxn               max length of char ngram [" << maxn << "]" << std::endl;
  std::cout << "  -t                  sampling threshold [" << t << "]" << std::endl;
  std::cout << "  -label              labels prefix [" << label << "]" << std::endl;
  std::cout << "\nThe following arguments for training are optional:" << std::endl;
  std::cout << "  -lr                 learning rate [" << lr << "]" << std::endl;
  std::cout << "  -lrUpdateRate       change the rate of updates for the learning rate [" << lrUpdateRate << "]" << std::endl;
  std::cout << "  -dim                size of word vectors [" << dim << "]" << std::endl;
  std::cout << "  -ws                 size of the context window [" << ws << "]" << std::endl;
  std::cout << "  -epoch              number of epochs [" << epoch << "]" << std::endl;
  std::cout << "  -neg                number of negatives sampled [" << neg << "]" << std::endl;
  std::cout << "  -loss               loss function {ns, hs, softmax, one-vs-all} [" << lossToString(loss) << "]" << std::endl;
  std::cout << "  -thread             number of threads (set to 1 to ensure reproducible results) [" << thread << "]" << std::endl;
  std::cout << "  -pretrainedVectors  pretrained word vectors for supervised learning [" << pretrainedVectors << "]" << std::endl;
  std::cout << "  -saveOutput         whether output params should be saved [" << (saveOutput ? "true" : "false") << "]" << std::endl;
  std::cout << "  -seed               random generator seed  [" << seed << "]" << std::endl;
  std::cout << "\nThe following arguments are for autotune:" << std::endl;
  std::cout << "  -autotune-validation            validation file to be used for evaluation" << std::endl;
  std::cout << "  -autotune-metric                metric objective {f1, f1:labelname} [" << autotuneMetric << "]" << std::endl;
  std::cout << "  -autotune-predictions           number of predictions used for evaluation  [" << autotunePredictions << "]" << std::endl;
  std::cout << "  -autotune-duration              maximum duration in seconds [" << autotuneDuration << "]" << std::endl;
  std::cout << "  -autotune-modelsize             constraint model file size [] (empty = do not quantize)" << std::endl;
  std::cout << "\nThe following arguments for quantization are optional:" << std::endl;
  std::cout << "  -cutoff             number of words and ngrams to retain [" << cutoff << "]" << std::endl;
  std::cout << "  -retrain            whether embeddings are finetuned if a cutoff is applied [" << (retrain ? "true" : "false") << "]" << std::endl;
  std::cout << "  -qnorm              whether the norm is quantized separately [" << (qnorm ? "true" : "false") << "]" << std::endl;
  std::cout << "  -qout               whether the classifier is quantized [" << (qout ? "true" : "false") << "]" << std::endl;
  std::cout << "  -dsub               size of each sub-vector [" << dsub << "]" << std::endl;
}

void Args::parseArgs(const std::vector<std::string>& args) {
  std::string command = args[1];
  if (command == "supervised") {
    model = model_name::sup;
    loss = loss_name::softmax;
    minCount = 1;
    minn = 0;
    maxn = 0;
    lr = 0.1;
  } else if (command == "cbow") {
    model = model_name::cbow;
  } else if (command == "skipgram") {
    model = model_name::sg;
  }

  for (size_t ai = 2; ai < args.size(); ai++) {
    if (args[ai][0] != '-') {
      std::cout << "Provided argument cannot be parsed: " << args[ai] << std::endl;
      printHelp();
      exit(1);
    }
    if (args[ai] == "-h") {
      std::cout << "Here is the help! Usage:" << std::endl;
      printHelp();
      exit(1);
    }
    if (ai == args.size() - 1) {
      std::cout << args[ai] << " is missing an argument" << std::endl;
      printHelp();
      exit(1);
    }
    std::string flag = args[ai];
    std::string val = args[ai + 1];
    ai++;

    if (flag == "-input") {
      input = val;
    } else if (flag == "-output") {
      output = val;
    } else if (flag == "-lr") {
      lr = std::stod(val);
    } else if (flag == "-lrUpdateRate") {
      lrUpdateRate = std::stoi(val);
    } else if (flag == "-dim") {
      dim = std::stoi(val);
    } else if (flag == "-ws") {
      ws = std::stoi(val);
    } else if (flag == "-epoch") {
      epoch = std::stoi(val);
    } else if (flag == "-minCount") {
      minCount = std::stoi(val);
    } else if (flag == "-minCountLabel") {
      minCountLabel = std::stoi(val);
    } else if (flag == "-neg") {
      neg = std::stoi(val);
    } else if (flag == "-wordNgrams") {
      wordNgrams = std::stoi(val);
    } else if (flag == "-loss") {
      if (val == "hs") loss = loss_name::hs;
      else if (val == "ns") loss = loss_name::ns;
      else if (val == "softmax") loss = loss_name::softmax;
      else if (val == "one-vs-all" || val == "ova") loss = loss_name::ova;
      else {
        std::cout << "Unknown loss: " << val << std::endl;
        printHelp();
        exit(1);
      }
    } else if (flag == "-bucket") {
      bucket = std::stoi(val);
    } else if (flag == "-minn") {
      minn = std::stoi(val);
    } else if (flag == "-maxn") {
      maxn = std::stoi(val);
    } else if (flag == "-thread") {
      thread = std::stoi(val);
    } else if (flag == "-t") {
      t = std::stod(val);
    } else if (flag == "-label") {
      label = val;
    } else if (flag == "-verbose") {
      verbose = std::stoi(val);
    } else if (flag == "-pretrainedVectors") {
      pretrainedVectors = val;
    } else if (flag == "-saveOutput") {
      saveOutput = (val == "true" || val == "1");
    } else if (flag == "-seed") {
      seed = std::stoi(val);
    } else if (flag == "-autotune-validation") {
      autotuneValidation = val;
    } else if (flag == "-autotune-metric") {
      autotuneMetric = val;
    } else if (flag == "-autotune-predictions") {
      autotunePredictions = std::stoi(val);
    } else if (flag == "-autotune-duration") {
      autotuneDuration = std::stoi(val);
    } else if (flag == "-autotune-modelsize") {
      autotuneModelSize = val;
    } else if (flag == "-cutoff") {
      cutoff = std::stoi(val);
    } else if (flag == "-retrain") {
      retrain = (val == "true" || val == "1");
    } else if (flag == "-qnorm") {
      qnorm = (val == "true" || val == "1");
    } else if (flag == "-qout") {
      qout = (val == "true" || val == "1");
    } else if (flag == "-dsub") {
      dsub = std::stoi(val);
    } else {
      std::cout << "Unknown argument: " << flag << std::endl;
      printHelp();
      exit(1);
    }
  }

  if (input.empty() || output.empty()) {
    std::cout << "Empty input or output path." << std::endl;
    printHelp();
    exit(1);
  }
}

void Args::save(std::ostream& out) const {
  out.write(reinterpret_cast<const char*>(&dim), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&ws), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&epoch), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&minCount), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&neg), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&wordNgrams), sizeof(int32_t));
  int32_t l = static_cast<int32_t>(loss);
  out.write(reinterpret_cast<const char*>(&l), sizeof(int32_t));
  int32_t m = static_cast<int32_t>(model);
  out.write(reinterpret_cast<const char*>(&m), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&bucket), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&minn), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&maxn), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&lrUpdateRate), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&t), sizeof(double));
}

void Args::load(std::istream& in) {
  in.read(reinterpret_cast<char*>(&dim), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&ws), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&epoch), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&minCount), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&neg), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&wordNgrams), sizeof(int32_t));
  int32_t l;
  in.read(reinterpret_cast<char*>(&l), sizeof(int32_t));
  loss = static_cast<loss_name>(l);
  int32_t m;
  in.read(reinterpret_cast<char*>(&m), sizeof(int32_t));
  model = static_cast<model_name>(m);
  in.read(reinterpret_cast<char*>(&bucket), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&minn), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&maxn), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&lrUpdateRate), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&t), sizeof(double));
}

void Args::dump(std::ostream& out) const {
  out << "dim " << dim << "\n";
  out << "ws " << ws << "\n";
  out << "epoch " << epoch << "\n";
  out << "minCount " << minCount << "\n";
  out << "neg " << neg << "\n";
  out << "wordNgrams " << wordNgrams << "\n";
  out << "loss " << lossToString(loss) << "\n";
  out << "model " << modelToString(model) << "\n";
  out << "bucket " << bucket << "\n";
  out << "minn " << minn << "\n";
  out << "maxn " << maxn << "\n";
  out << "lrUpdateRate " << lrUpdateRate << "\n";
  out << "t " << t << "\n";
}
EOF"}

