{"command":"cat << 'EOF' > src/matrix.cc
#include "matrix.h"
#include <random>
#include <cmath>
#include <stdexcept>
#include <cstdint>

Matrix::Matrix() : m_(0), n_(0) {}

Matrix::Matrix(int64_t m, int64_t n) : m_(m), n_(n), data_(m * n, 0.0) {}

void Matrix::zero() {
  std::fill(data_.begin(), data_.end(), 0.0);
}

void Matrix::uniform(real a) {
  std::minstd_rand rng(1);
  std::uniform_real_distribution<real> dist(-a, a);
  for (size_t i = 0; i < data_.size(); i++) {
    data_[i] = dist(rng);
  }
}

real Matrix::dotRow(const Vector& vec, int64_t i) const {
  real d = 0.0;
  const real* row = &data_[i * n_];
  for (int64_t j = 0; j < n_; j++) {
    d += row[j] * vec[j];
  }
  return d;
}

void Matrix::addRow(const Vector& vec, int64_t i, real a) {
  real* row = &data_[i * n_];
  for (int64_t j = 0; j < n_; j++) {
    row[j] += a * vec[j];
  }
}

void Matrix::addRowToVector(Vector& vec, int64_t i, real a) const {
  const real* row = &data_[i * n_];
  for (int64_t j = 0; j < n_; j++) {
    vec[j] += a * row[j];
  }
}

void Matrix::save(std::ostream& out) const {
  out.write(reinterpret_cast<const char*>(&m_), sizeof(int64_t));
  out.write(reinterpret_cast<const char*>(&n_), sizeof(int64_t));
  if (m_ * n_ > 0) {
    out.write(reinterpret_cast<const char*>(data_.data()), m_ * n_ * sizeof(real));
  }
}

