{"command":"cat << 'EOF' > src/meter.cc
#include "meter.h"

Meter::Meter(std::shared_ptr<Args> args)
    : args_(args),
      nexamples_(0),
      totalPredicted_(0),
      totalGold_(0),
      totalCorrect_(0) {}

void Meter::log(
    const std::vector<int32_t>& labels,
    const std::vector<std::pair<real, int32_t>>& predictions) {
  if (labels.empty()) return;
  nexamples_++;
  totalGold_ += labels.size();
  for (int32_t l : labels) {
    gold_[l]++;
  }

  for (const auto& pred : predictions) {
    int32_t l = pred.second;
    predicted_[l]++;
    totalPredicted_++;
    if (std::find(labels.begin(), labels.end(), l) != labels.end()) {
      correct_[l]++;
      totalCorrect_++;
    }
  }
}

void Meter::writeGeneral(std::ostream& out, int32_t k) const {
  out << "N\t" << nexamples_ << "\n";
  if (totalPredicted_ == 0) {
    out << "P@" << k << "\tnan\n";
  } else {
    real p = static_cast<real>(totalCorrect_) / totalPredicted_;
    out << "P@" << k << "\t" << std::setprecision(3) << p << "\n";
  }
  if (totalGold_ == 0) {
    out << "R@" << k << "\tnan\n";
  } else {
    real r = static_cast<real>(totalCorrect_) / totalGold_;
    out << "R@" << k << "\t" << std::setprecision(3) << r << "\n";
  }
}

void Meter::writePerLabel(
    std::ostream& out,
    std::shared_ptr<Dictionary> dict,
    int32_t k) const {
  int32_t nlabels = dict->nlabels();
  int32_t nwords = dict->nwords();
  for (int32_t i = 0; i < nlabels; i++) {
    std::string label_str = dict->getWord(i + nwords);
    auto it_pred = predicted_.find(i);
    auto it_gold = gold_.find(i);
    auto it_corr = correct_.find(i);

    int64_t pred_c = (it_pred != predicted_.end()) ? it_pred->second : 0;
    int64_t gold_c = (it_gold != gold_.end()) ? it_gold->second : 0;
    int64_t corr_c = (it_corr != correct_.end()) ? it_corr->second : 0;

    if (pred_c == 0 && gold_c == 0) {
      out << "F1-Score : --------  Precision : --------  Recall : --------   " << label_str << "\n";
    } else {
      real precision = (pred_c > 0) ? (static_cast<real>(corr_c) / pred_c) : 0.0;
      real recall = (gold_c > 0) ? (static_cast<real>(corr_c) / gold_c) : 0.0;
      real f1 = (precision + recall > 0) ? (2 * precision * recall / (precision + recall)) : 0.0;

      out << "F1-Score : " << std::fixed << std::setprecision(6) << f1
          << "  Precision : " << std::fixed << std::setprecision(6) << precision
          << "  Recall : " << std::fixed << std::setprecision(6) << recall
          << "   " << label_str << "\n";
    }
  }
  writeGeneral(out, k);
}
EOF"}

