#pragma once

#include <vector>
#include <memory>
#include <utility>
#include <random>
#include "args.h"
#include "matrix.h"
#include "qmatrix.h"
#include "real.h"

class Model {
 public:
  Model(
      std::shared_ptr<Matrix> wi,
      std::shared_ptr<Matrix> wo,
      std::shared_ptr<Args> args,
      int32_t seed);

  void setTargetCounts(const std::vector<int64_t>& counts);
  void computeHidden(const std::vector<int32_t>& input, Vector& hidden) const;
  void computeOutput(Vector& hidden, Vector& output) const;

  void predict(
      const std::vector<int32_t>& input,
      int32_t k,
      real threshold,
      std::vector<std::pair<real, int32_t>>& heap);

  void predict(
      int32_t k,
      real threshold,
      std::vector<std::pair<real, int32_t>>& heap,
      Vector& hidden,
      Vector& output);

  void update(
      const std::vector<int32_t>& input,
      const std::vector<int32_t>& targets,
      int32_t targetIndex,
      real lr);

  real sigmoid(real x) const;
  real log(real x) const;

  std::shared_ptr<Matrix> wi_;
  std::shared_ptr<Matrix> wo_;
  std::shared_ptr<Args> args_;

 private:
  static const int32_t SIGMOID_TABLE_SIZE = 512;
  static const int32_t MAX_SIGMOID = 8;
  static const int32_t LOG_TABLE_SIZE = 512;

  std::vector<real> t_sigmoid_;
  std::vector<real> t_log_;

  Vector hidden_;
  Vector output_;
  Vector grad_;

  std::vector<int32_t> neg_table_;
  int32_t negpos_;

  std::minstd_rand rng_;

  void initSigmoid();
  void initLog();
  void initTableNegatives(const std::vector<int64_t>& counts);

  real lossNS(int32_t target, real lr);
  real lossSoftmax(int32_t target, real lr);
};
