{"command":"cat << 'EOF' > src/model.cc
#include "model.h"
#include <cmath>
#include <algorithm>
#include <stdexcept>
#include <iostream>

Model::Model(
    std::shared_ptr<Matrix> wi,
    std::shared_ptr<Matrix> wo,
    std::shared_ptr<Args> args,
    int32_t seed)
    : wi_(wi),
      wo_(wo),
      args_(args),
      hidden_(args->dim),
      output_(wo ? wo->m_ : 0),
      grad_(args->dim),
      negpos_(0),
      rng_(seed) {
  initSigmoid();
  initLog();
}

void Model::initSigmoid() {
  t_sigmoid_.resize(SIGMOID_TABLE_SIZE + 1);
  for (int i = 0; i <= SIGMOID_TABLE_SIZE; i++) {
    real x = (real(i) >> 9 << 4) - MAX_SIGMOID; // or x = real(i * 2 * MAX_SIGMOID) / SIGMOID_TABLE_SIZE - MAX_SIGMOID;
    x = real(i) * 2 * MAX_SIGMOID / SIGMOID_TABLE_SIZE - MAX_SIGMOID;
    t_sigmoid_[i] = 1.0 / (1.0 + std::exp(-x));
  }
}

void Model::initLog() {
  t_log_.resize(LOG_TABLE_SIZE + 1);
  for (int i = 0; i <= LOG_TABLE_SIZE; i++) {
    real x = (real(i) + 1e-5) / LOG_TABLE_SIZE;
    t_log_[i] = std::log(x);
  }
}

real Model::sigmoid(real x) const {
  if (x < -MAX_SIGMOID) return 0.0;
  if (x > MAX_SIGMOID) return 1.0;
  int i = int((x + MAX_SIGMOID) * SIGMOID_TABLE_SIZE / (2 * MAX_SIGMOID));
  return t_sigmoid_[i];
}

real Model::log(real x) const {
  if (x > 1.0) return 0.0;
  int i = int(x * LOG_TABLE_SIZE);
  return t_log_[i];
}

void Model::initTableNegatives(const std::vector<int64_t>& counts) {
  real z = 0.0;
  for (size_t i = 0; i < counts.size(); i++) {
    z += std::pow(counts[i], 0.75);
  }
  neg_table_.reserve(10000000);
  for (size_t i = 0; i < counts.size(); i++) {
    real c = std::pow(counts[i], 0.75);
    for (int j = 0; j < c * 10000000 / z; j++) {
      neg_table_.push_back(i);
    }
  }
}

void Model::setTargetCounts(const std::vector<int64_t>& counts) {
  if (args_->loss == loss_name::ns) {
    initTableNegatives(counts);
  }
}

void Model::computeHidden(const std::vector<int32_t>& input, Vector& hidden) const {
  hidden.zero();
  if (input.empty()) return;
  for (auto i : input) {
    if (i < wi_->m_) {
      hidden.addRow(*wi_, i);
    }
  }
  hidden.mul(1.0 / input.size());
}

void Model::computeOutput(Vector& hidden, Vector& output) const {
  if (!wo_) return;
  for (int64_t i = 0; i < wo_->m_; i++) {
    output[i] = wo_->dotRow(hidden, i);
  }
}

void Model::predict(
    const std::vector<int32_t>& input,
    int32_t k,
    real threshold,
    std::vector<std::pair<real, int32_t>>& heap) {
  if (input.empty()) return;
  computeHidden(input, hidden_);
  predict(k, threshold, heap, hidden_, output_);
}

void Model::predict(
    int32_t k,
    real threshold,
    std::vector<std::pair<real, int32_t>>& heap,
    Vector& hidden,
    Vector& output) {
  heap.clear();
  if (!wo_ || wo_->m_ == 0) return;
  computeOutput(hidden, output);

  if (args_->loss == loss_name::softmax) {
    // Softmax probabilities
    real max_val = output[0];
    for (int64_t i = 1; i < wo_->m_; i++) {
      if (output[i] > max_val) max_val = output[i];
    }
    real sum = 0.0;
    for (int64_t i = 0; i < wo_->m_; i++) {
      output[i] = std::exp(output[i] - max_val);
      sum += output[i];
    }
    for (int64_t i = 0; i < wo_->m_; i++) {
      output[i] /= sum;
    }
  } else {
    // Sigmoid probabilities
    for (int64_t i = 0; i < wo_->m_; i++) {
      output[i] = sigmoid(output[i]);
    }
  }

  for (int64_t i = 0; i < wo_->m_; i++) {
    if (output[i] >= threshold) {
      heap.push_back({output[i], static_cast<int32_t>(i)});
    }
  }

  std::sort(heap.begin(), heap.end(), [](const std::pair<real, int32_t>& a, const std::pair<real, int32_t>& b) {
    return a.first > b.first;
  });

  if (k > 0 && static_cast<size_t>(k) < heap.size()) {
    heap.resize(k);
  }
}

real Model::lossSoftmax(int32_t target, real lr) {
  real max_val = output_[0];
  for (int64_t i = 1; i < wo_->m_; i++) {
    if (output_[i] > max_val) max_val = output_[i];
  }
  real sum = 0.0;
  for (int64_t i = 0; i < wo_->m_; i++) {
    output_[i] = std::exp(output_[i] - max_val);
    sum += output_[i];
  }
  for (int64_t i = 0; i < wo_->m_; i++) {
    output_[i] /= sum;
  }

  grad_.zero();
  for (int64_t i = 0; i < wo_->m_; i++) {
    real label = (i == target) ? 1.0 : 0.0;
    real alpha = lr * (output_[i] - label);
    grad_.addRow(*wo_, i, alpha);
    wo_->addRow(hidden_, i, -alpha);
  }
  return -std::log(std::max(output_[target], real(1e-9)));
}

real Model::lossNS(int32_t target, real lr) {
  grad_.zero();
  real loss = 0.0;
  for (int n = 0; n <= args_->neg; n++) {
    int32_t sample;
    real label;
    if (n == 0) {
      sample = target;
      label = 1.0;
    } else {
      if (neg_table_.empty()) {
        sample = rng_() % wo_->m_;
      } else {
        sample = neg_table_[negpos_ % neg_table_.size()];
        negpos_++;
      }
      if (sample == target) continue;
      label = 0.0;
    }
    real score = wo_->dotRow(hidden_, sample);
    real pred = sigmoid(score);
    real alpha = lr * (pred - label);
    grad_.addRow(*wo_, sample, alpha);
    wo_->addRow(hidden_, sample, -alpha);
  }
  return loss;
}

void Model::update(
    const std::vector<int32_t>& input,
    const std::vector<int32_t>& targets,
    int32_t targetIndex,
    real lr) {
  if (input.empty() || targets.empty()) return;
  computeHidden(input, hidden_);

  int32_t target = targets[targetIndex];
  if (args_->loss == loss_name::softmax) {
    computeOutput(hidden_, output_);
    lossSoftmax(target, lr);
  } else {
    lossNS(target, lr);
  }

  real alpha = 1.0 / input.size();
  for (auto i : input) {
    if (i < wi_->m_) {
      wi_->addRow(grad_, i, -alpha);
    }
  }
}
