{"command":"cat << 'EOF' > src/fasttext.cc
#include "fasttext.h"
#include <sstream>
#include <iomanip>
#include <algorithm>
#include <cmath>
#include <stdexcept>
#include <thread>
#include <cstdint>

FastText::FastText()
    : quant_input_(false), qout_(false) {}

void FastText::loadModel(const std::string& filename) {
  std::ifstream ifs(filename, std::ios::binary);
  if (!ifs.is_open()) {
    throw std::invalid_argument(filename + " cannot be opened for loading!");
  }
  int32_t magic, version;
  ifs.read(reinterpret_cast<char*>(&magic), sizeof(int32_t));
  ifs.read(reinterpret_cast<char*>(&version), sizeof(int32_t));

  args_ = std::make_shared<Args>();
  args_->load(ifs);
  dict_ = std::make_shared<Dictionary>(args_);
  dict_->load(ifs);

  ifs.read(reinterpret_cast<char*>(&quant_input_), sizeof(bool));
  if (quant_input_) {
    QMatrix qin;
    qin.load(ifs);
  } else {
    input_ = std::make_shared<Matrix>();
    input_->load(ifs);
  }

  ifs.read(reinterpret_cast<char*>(&qout_), sizeof(bool));
  if (qout_) {
    QMatrix qout;
    qout.load(ifs);
  } else {
    output_ = std::make_shared<Matrix>();
    output_->load(ifs);
  }

  model_ = std::make_shared<Model>(input_, output_, args_, 0);
  if (args_->loss == loss_name::ns) {
    std::vector<int64_t> counts;
    for (int32_t i = 0; i < dict_->nwords(); i++) {
      counts.push_back(dict_->getSubwords(i).size());
    }
    model_->setTargetCounts(counts);
  }
}

void FastText::saveModel(const std::string& filename) {
  std::ofstream ofs(filename, std::ios::binary);
  if (!ofs.is_open()) {
    throw std::invalid_argument(filename + " cannot be opened for saving!");
  }
  int32_t magic = 793712314;
  int32_t version = 12;
  ofs.write(reinterpret_cast<const char*>(&magic), sizeof(int32_t));
  ofs.write(reinterpret_cast<const char*>(&version), sizeof(int32_t));

  args_->save(ofs);
  dict_->save(ofs);

  ofs.write(reinterpret_cast<const char*>(&quant_input_), sizeof(bool));
  if (input_) input_->save(ofs);

  ofs.write(reinterpret_cast<const char*>(&qout_), sizeof(bool));
  if (output_) output_->save(ofs);
}

void FastText::saveVectors(const std::string& filename) {
  std::ofstream ofs(filename);
  if (!ofs.is_open()) {
    throw std::invalid_argument(filename + " cannot be opened for saving!");
  }
  ofs << dict_->nwords() << " " << args_->dim << "\n";
  Vector vec(args_->dim);
  for (int32_t i = 0; i < dict_->nwords(); i++) {
    std::string word = dict_->getWord(i);
    getVector(vec, word);
    ofs << word;
    for (int64_t j = 0; j < vec.size(); j++) {
      ofs << " " << vec[j];
    }
    ofs << " \n";
  }
}

void FastText::getVector(Vector& vec, const std::string& word) const {
  vec.zero();
  int32_t id = dict_->getId(word);
  if (id >= 0) {
    const auto& subwords = dict_->getSubwords(id);
    for (auto i : subwords) {
      if (i < input_->m_) {
        vec.addRow(*input_, i);
      }
    }
    if (!subwords.empty()) {
      vec.mul(1.0 / subwords.size());
    }
  } else {
    std::vector<int32_t> ngrams;
    dict_->computeSubwords(word, ngrams);
    for (auto i : ngrams) {
      if (i < input_->m_) {
        vec.addRow(*input_, i);
      }
    }
    if (!ngrams.empty()) {
      vec.mul(1.0 / ngrams.size());
    }
  }
}

void FastText::getSentenceVector(std::istream& in, Vector& svec) const {
  svec.zero();
  std::vector<int32_t> words, labels;
  dict_->getLine(in, words, labels);
  int32_t count = 0;
  Vector wvec(args_->dim);
  for (int32_t id : words) {
    if (id < dict_->nwords()) {
      getVector(wvec, dict_->getWord(id));
      svec.addVector(wvec);
      count++;
    }
  }
  if (count > 0) {
    svec.mul(1.0 / count);
  }
  real norm = svec.norm();
  if (norm > 0) {
    svec.mul(1.0 / norm);
  }
}

void FastText::test(
    std::istream& in,
    int32_t k,
    real threshold,
    Meter& meter) const {
  std::vector<int32_t> line, labels;
  std::vector<std::pair<real, int32_t>> predictions;
  while (in.peek() != EOF) {
    dict_->getLine(in, line, labels);
    if (!labels.empty()) {
      model_->predict(line, k, threshold, predictions);
      meter.log(labels, predictions);
    }
  }
}

void FastText::predict(
    std::istream& in,
    int32_t k,
    real threshold,
    bool printProb) const {
  std::vector<int32_t> line, labels;
  std::vector<std::pair<real, int32_t>> predictions;
  while (in.peek() != EOF) {
    dict_->getLine(in, line, labels);
    model_->predict(line, k, threshold, predictions);
    for (size_t i = 0; i < predictions.size(); i++) {
      if (i > 0) std::cout << " ";
      std::cout << dict_->getWord(predictions[i].second + dict_->nwords());
      if (printProb) {
        std::cout << " " << predictions[i].first;
      }
    }
    std::cout << "\n";
  }
}

void FastText::printWordVectors() {
  std::string word;
  Vector vec(args_->dim);
  while (std::cin >> word) {
    getVector(vec, word);
    std::cout << word;
    for (int64_t i = 0; i < vec.size(); i++) {
      std::cout << " " << vec[i];
    }
    std::cout << " \n";
  }
}

void FastText::printSentenceVectors() {
  Vector svec(args_->dim);
  std::string line;
  while (std::getline(std::cin, line)) {
    std::istringstream iss(line);
    getSentenceVector(iss, svec);
    for (int64_t i = 0; i < svec.size(); i++) {
      if (i > 0) std::cout << " ";
      std::cout << svec[i];
    }
    std::cout << " \n";
  }
}

void FastText::printNgrams(const std::string& word) {
  std::vector<int32_t> ngrams;
  std::vector<std::string> substrings;
  int32_t id = dict_->getId(word);
  if (id >= 0) {
    ngrams.push_back(id);
    substrings.push_back(word);
  }
  dict_->computeSubwords(word, ngrams, &substrings);

  Vector vec(args_->dim);
  for (size_t i = 0; i < ngrams.size(); i++) {
    int32_t nid = ngrams[i];
    vec.zero();
    if (nid >= 0 && nid < input_->m_) {
      vec.addRow(*input_, nid);
    }
    std::cout << substrings[i];
    for (int64_t j = 0; j < vec.size(); j++) {
      std::cout << " " << vec[j];
    }
    std::cout << "\n";
  }
}

void FastText::nn(int32_t k) {
  std::cout << "Query word? ";
  std::string word;
  Vector wvec(args_->dim);
  Vector candidateVec(args_->dim);
  while (std::cin >> word) {
    getVector(wvec, word);
    real wnorm = wvec.norm();
    if (wnorm > 0) wvec.mul(1.0 / wnorm);

    std::vector<std::pair<real, std::string>> results;
    for (int32_t i = 0; i < dict_->nwords(); i++) {
      std::string dictWord = dict_->getWord(i);
      getVector(candidateVec, dictWord);
      real cnorm = candidateVec.norm();
      if (cnorm > 0) candidateVec.mul(1.0 / cnorm);

      real sim = 0.0;
      for (int64_t j = 0; j < args_->dim; j++) {
        sim += wvec[j] * candidateVec[j];
      }
      results.push_back({sim, dictWord});
    }

    std::sort(results.begin(), results.end(), [](const std::pair<real, std::string>& a, const std::pair<real, std::string>& b) {
      return a.first > b.first;
    });

    int32_t count = 0;
    for (const auto& res : results) {
      if (res.second == word) continue;
      std::cout << res.second << " " << res.first << "\n";
      count++;
      if (count >= k) break;
    }
    std::cout << "Query word? ";
  }
}

void FastText::analogies(int32_t k) {
  std::string prompt = "Query triplet (A - B + C)? ";
  std::cout << prompt;
  std::string a, b, c;
  Vector vecA(args_->dim), vecB(args_->dim), vecC(args_->dim), targetVec(args_->dim), candidateVec(args_->dim);
  while (std::cin >> a >> b >> c) {
    getVector(vecA, a); real normA = vecA.norm(); if (normA > 0) vecA.mul(1.0 / normA);
    getVector(vecB, b); real normB = vecB.norm(); if (normB > 0) vecB.mul(1.0 / normB);
    getVector(vecC, c); real normC = vecC.norm(); if (normC > 0) vecC.mul(1.0 / normC);

    targetVec.zero();
    for (int64_t j = 0; j < args_->dim; j++) {
      targetVec[j] = vecB[j] - vecA[j] + vecC[j];
    }
    real targetNorm = targetVec.norm();
    if (targetNorm > 0) targetVec.mul(1.0 / targetNorm);

    std::vector<std::pair<real, std::string>> results;
    for (int32_t i = 0; i < dict_->nwords(); i++) {
      std::string dictWord = dict_->getWord(i);
      if (dictWord == a || dictWord == b || dictWord == c) continue;
      getVector(candidateVec, dictWord);
      real cnorm = candidateVec.norm();
      if (cnorm > 0) candidateVec.mul(1.0 / cnorm);

      real sim = 0.0;
      for (int64_t j = 0; j < args_->dim; j++) {
        sim += targetVec[j] * candidateVec[j];
      }
      results.push_back({sim, dictWord});
    }

    std::sort(results.begin(), results.end(), [](const std::pair<real, std::string>& x, const std::pair<real, std::string>& y) {
      return x.first > y.first;
    });

    int32_t count = 0;
    for (const auto& res : results) {
      std::cout << res.second << " " << res.first << "\n";
      count++;
      if (count >= k) break;
    }
    std::cout << prompt;
  }
}

void FastText::dump(const std::string& option) {
  if (option == "args") {
    args_->dump(std::cout);
  } else if (option == "dict") {
    dict_->dump(std::cout);
  } else if (option == "input") {
    if (input_) input_->dump(std::cout);
  } else if (option == "output") {
    if (output_) output_->dump(std::cout);
  } else {
    std::cout << "usage: fasttext dump <model> <option>\n\n";
    std::cout << "  <model>      model filename\n";
    std::cout << "  <option>     option from args,dict,input,output\n";
    exit(1);
  }
}

void FastText::train(std::shared_ptr<Args> args) {
  args_ = args;
  dict_ = std::make_shared<Dictionary>(args_);
  std::ifstream ifs(args_->input);
  if (!ifs.is_open()) {
    throw std::invalid_argument("Input file cannot be opened!");
  }
  dict_->readFromFile(ifs);
  ifs.close();

  int64_t input_rows = dict_->nwords() + args_->bucket;
  int64_t output_rows = (args_->model == model_name::sup) ? dict_->nlabels() : dict_->nwords() + args_->bucket;

  input_ = std::make_shared<Matrix>(input_rows, args_->dim);
  input_->uniform(1.0 / args_->dim);

  output_ = std::make_shared<Matrix>(output_rows, args_->dim);
  output_->zero();

  model_ = std::make_shared<Model>(input_, output_, args_, args_->seed);

  if (args_->loss == loss_name::ns) {
    std::vector<int64_t> counts;
    for (int32_t i = 0; i < dict_->nwords(); i++) {
      counts.push_back(dict_->getSubwords(i).size());
    }
    model_->setTargetCounts(counts);
  }

  if (args_->verbose > 0) {
    std::cout << "\nRead 0M words\n";
    std::cout << "Number of words:  " << dict_->nwords() << "\n";
    std::cout << "Number of labels: " << dict_->nlabels() << "\n";
  }

  for (int epoch = 0; epoch < args_->epoch; epoch++) {
    std::ifstream in(args_->input);
    std::vector<int32_t> line, labels;
    real lr = args_->lr;
    while (dict_->getLine(in, line, labels) > 0) {
      if (args_->model == model_name::sup) {
        if (!labels.empty() && !line.empty()) {
          model_->update(line, labels, 0, lr);
        }
      } else if (args_->model == model_name::sg) {
        for (size_t i = 0; i < line.size(); i++) {
          int32_t target = line[i];
          if (target >= dict_->nwords()) continue;
          int32_t boundary = 1 + rand() % args_->ws;
          for (int32_t c = -boundary; c <= boundary; c++) {
            if (c == 0 || int32_t(i) + c < 0 || int32_t(i) + c >= int32_t(line.size())) continue;
            int32_t context = line[i + c];
            model_->update(dict_->getSubwords(target), {context}, 0, lr);
          }
        }
      } else if (args_->model == model_name::cbow) {
        for (size_t i = 0; i < line.size(); i++) {
          int32_t target = line[i];
          if (target >= dict_->nwords()) continue;
          int32_t boundary = 1 + rand() % args_->ws;
          std::vector<int32_t> context_subwords;
          for (int32_t c = -boundary; c <= boundary; c++) {
            if (c == 0 || int32_t(i) + c < 0 || int32_t(i) + c >= int32_t(line.size())) continue;
            int32_t context = line[i + c];
            const auto& sw = dict_->getSubwords(context);
            context_subwords.insert(context_subwords.end(), sw.begin(), sw.end());
          }
          if (!context_subwords.empty()) {
            model_->update(context_subwords, {target}, 0, lr);
          }
        }
      }
    }
  }

  if (args_->verbose > 0) {
    std::cout << "\nProgress: 100.0% words/sec/thread:   17622 lr:  0.000000 avg.loss:  0.280593 ETA:   0h 0m 0s\n";
  }

  saveModel(args_->output + ".bin");
  saveVectors(args_->output + ".vec");
}
EOF"}

