#include "dictionary.h"
#include <algorithm>
#include <cmath>
#include <iostream>
#include <cstdint>

const std::string Dictionary::EOS = "</s>";
const std::string Dictionary::BOW = "<";
const std::string Dictionary::EOW = ">";

Dictionary::Dictionary(std::shared_ptr<Args> args)
    : args_(args),
      word2int_(MAX_VOCAB_SIZE, -1),
      size_(0),
      nwords_(0),
      nlabels_(0),
      ntokens_(0),
      pruneidx_size_(-1) {}

int32_t Dictionary::size() const { return size_; }
int32_t Dictionary::nwords() const { return nwords_; }
int32_t Dictionary::nlabels() const { return nlabels_; }
int64_t Dictionary::ntokens() const { return ntokens_; }

uint32_t Dictionary::hash(const std::string& str) const {
  uint32_t h = 2166136261u;
  for (size_t i = 0; i < str.size(); i++) {
    h = h ^ uint32_t(int8_t(str[i]));
    h = h * 16777619u;
  }
  return h;
}

int32_t Dictionary::find(const std::string& w) const {
  return find(w, hash(w));
}

int32_t Dictionary::find(const std::string& w, uint32_t h) const {
  int32_t id = h % MAX_VOCAB_SIZE;
  while (word2int_[id] != -1 && words_[word2int_[id]].word != w) {
    id = (id + 1) % MAX_VOCAB_SIZE;
  }
  return id;
}

int32_t Dictionary::getId(const std::string& w) const {
  int32_t id = find(w);
  return word2int_[id];
}

int32_t Dictionary::getId(const std::string& w, uint32_t h) const {
  int32_t id = find(w, h);
  return word2int_[id];
}

entry_type Dictionary::getType(int32_t id) const {
  return words_[id].type;
}

entry_type Dictionary::getType(const std::string& w) const {
  return (w.find(args_->label) == 0) ? entry_type::label : entry_type::word;
}

std::string Dictionary::getWord(int32_t id) const {
  return words_[id].word;
}

const std::vector<int32_t>& Dictionary::getSubwords(int32_t id) const {
  return words_[id].subwords;
}

void Dictionary::add(const std::string& w) {
  int32_t h = find(w);
  ntokens_++;
  if (word2int_[h] == -1) {
    entry e;
    e.word = w;
    e.count = 1;
    e.type = getType(w);
    words_.push_back(e);
    word2int_[h] = size_;
    size_++;
  } else {
    words_[word2int_[h]].count++;
  }
}

bool Dictionary::readWord(std::istream& in, std::string& word) const {
  word.clear();
  int c;
  while ((c = in.get()) != EOF) {
    if (c == ' ' || c == '\t' || c == '\v' || c == '\f' || c == '\r') {
      if (!word.empty()) {
        return true;
      }
    } else if (c == '\n') {
      if (!word.empty()) {
        in.unget();
        return true;
      }
      word = EOS;
      return true;
    } else {
      word.push_back(static_cast<char>(c));
    }
  }
  return !word.empty();
}

void Dictionary::readFromFile(std::istream& in) {
  std::string word;
  int64_t minThreshold = 1;
  while (readWord(in, word)) {
    add(word);
    if (size_ > 0.75 * MAX_VOCAB_SIZE) {
      threshold(minThreshold, minThreshold);
      minThreshold++;
    }
  }
  threshold(args_->minCount, args_->minCountLabel);
  initTableDiscard();
  initNgrams();
}

void Dictionary::threshold(int64_t minCount, int64_t minCountLabel) {
  if (size_ == 0) return;
  std::sort(words_.begin(), words_.end(), [](const entry& a, const entry& b) {
    if (a.type != b.type) return a.type < b.type;
    return a.count > b.count;
  });

  size_ = 0;
  nwords_ = 0;
  nlabels_ = 0;
  std::fill(word2int_.begin(), word2int_.end(), -1);

  for (auto it = words_.begin(); it != words_.end(); ++it) {
    int64_t minc = (it->type == entry_type::word) ? minCount : minCountLabel;
    if (it->count >= minc) {
      word2int_[find(it->word)] = size_;
      size_++;
      if (it->type == entry_type::word) nwords_++;
      if (it->type == entry_type::label) nlabels_++;
    }
  }
  words_.erase(words_.begin() + size_, words_.end());
}

void Dictionary::initTableDiscard() {
  pdiscard_.resize(size_);
