    const std::vector<int32_t>& word_ids,
    int32_t n) const {
  int32_t size = word_ids.size();
  for (int32_t i = 0; i < size; i++) {
    uint64_t h = word_ids[i];
    for (int32_t j = i + 1; j < size && j < i + n; j++) {
      h = h * 116049371u + word_ids[j];
      int32_t id = nwords_ + (h % args_->bucket);
      line.push_back(id);
    }
  }
}

int32_t Dictionary::getLine(
    std::istream& in,
    std::vector<int32_t>& words,
    std::vector<int32_t>& labels) const {
  words.clear();
  labels.clear();
  int32_t ntokens = 0;
  std::string token;
  std::vector<int32_t> word_ids;

  while (readWord(in, token)) {
    if (token == EOS) break;
    int32_t id = getId(token);
    if (id < 0) {
      if (token.find(args_->label) != 0) {
        std::vector<int32_t> ngrams;
        computeSubwords(token, ngrams);
        words.insert(words.end(), ngrams.begin(), ngrams.end());
      }
    } else {
      entry_type type = words_[id].type;
      if (type == entry_type::word) {
        word_ids.push_back(id);
        words.push_back(id);
        for (int32_t i : words_[id].subwords) {
          if (i != id) words.push_back(i);
        }
      } else if (type == entry_type::label) {
        labels.push_back(id - nwords_);
      }
    }
    ntokens++;
  }

  if (args_->wordNgrams > 1) {
    addWordNgrams(words, word_ids, args_->wordNgrams);
  }

  if (args_->model != model_name::sup && ntokens > 0) {
    int32_t eos = getId(EOS);
    if (eos >= 0) words.push_back(eos);
  }
  return ntokens;
}

void Dictionary::save(std::ostream& out) const {
  out.write(reinterpret_cast<const char*>(&size_), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&nwords_), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&nlabels_), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&ntokens_), sizeof(int64_t));
  out.write(reinterpret_cast<const char*>(&pruneidx_size_), sizeof(int64_t));

  for (int32_t i = 0; i < size_; i++) {
    out.write(words_[i].word.data(), words_[i].word.size() + 1);
    out.write(reinterpret_cast<const char*>(&words_[i].count), sizeof(int64_t));
    int8_t t = static_cast<int8_t>(words_[i].type);
    out.write(reinterpret_cast<const char*>(&t), sizeof(int8_t));
  }

  if (pruneidx_size_ >= 0) {
    int32_t psize = pruneidx_.size();
    out.write(reinterpret_cast<const char*>(&psize), sizeof(int32_t));
    for (const auto& pair : pruneidx_) {
      out.write(reinterpret_cast<const char*>(&pair.first), sizeof(int32_t));
      out.write(reinterpret_cast<const char*>(&pair.second), sizeof(int32_t));
    }
  }
}

void Dictionary::load(std::istream& in) {
  words_.clear();
  std::fill(word2int_.begin(), word2int_.end(), -1);

  in.read(reinterpret_cast<char*>(&size_), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&nwords_), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&nlabels_), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&ntokens_), sizeof(int64_t));
  in.read(reinterpret_cast<char*>(&pruneidx_size_), sizeof(int64_t));

  for (int32_t i = 0; i < size_; i++) {
    entry e;
    char c;
    while (in.get(c) && c != '\0') {
      e.word.push_back(c);
    }
    in.read(reinterpret_cast<char*>(&e.count), sizeof(int64_t));
    int8_t t;
    in.read(reinterpret_cast<char*>(&t), sizeof(int8_t));
    e.type = static_cast<entry_type>(t);
    words_.push_back(e);
    word2int_[find(e.word)] = i;
  }

  if (pruneidx_size_ >= 0) {
    int32_t psize;
    in.read(reinterpret_cast<char*>(&psize), sizeof(int32_t));
    for (int32_t i = 0; i < psize; i++) {
      int32_t key, val;
      in.read(reinterpret_cast<char*>(&key), sizeof(int32_t));
      in.read(reinterpret_cast<char*>(&val), sizeof(int32_t));
      pruneidx_[key] = val;
    }
  }

  initTableDiscard();
  initNgrams();
}

void Dictionary::dump(std::ostream& out) const {
  out << size_ << "\n";
  for (int32_t i = 0; i < size_; i++) {
    out << words_[i].word << " " << words_[i].count << " ";
    if (words_[i].type == entry_type::word) out << "word\n";
    else out << "label\n";
  }
}
